package club.abelix.games.fakevival.listeners;

import club.abelix.games.fakevival.Game;
import club.abelix.games.fakevival.managers.*;
import club.abelix.games.fakevival.menus.MenuHolder;
import club.abelix.games.fakevival.mmo.MMOStatType;
import club.abelix.games.fakevival.util.CC;
import org.bukkit.*;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.block.Action;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.*;
import org.bukkit.persistence.*;
import java.util.*;

public final class CustomAnvilListener implements Listener {
 private static final Set<Material> ANVILS=Set.of(Material.ANVIL,Material.CHIPPED_ANVIL,Material.DAMAGED_ANVIL);
 private static final Set<Integer> INPUTS=Set.of(11,13);
 private final Game plugin;private final CustomEnchantManager enchants;private final CustomItemManager items;private final EconomyManager economy;private final ReforgeManager reforges;private final NamespacedKey actionKey;
 private final Map<UUID,Session> sessions=new HashMap<>();
 public CustomAnvilListener(Game plugin,CustomEnchantManager enchants,CustomItemManager items,EconomyManager economy){this.plugin=plugin;this.enchants=enchants;this.items=items;this.economy=economy;this.reforges=new ReforgeManager(plugin,items);actionKey=new NamespacedKey(plugin,"anvil_menu_action");}

 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void interact(PlayerInteractEvent e){if(e.getAction()!=Action.RIGHT_CLICK_BLOCK||e.getClickedBlock()==null||!ANVILS.contains(e.getClickedBlock().getType()))return;e.setCancelled(true);e.setUseInteractedBlock(Event.Result.DENY);e.setUseItemInHand(Event.Result.DENY);open(e.getPlayer(),0);}
 public void open(Player p,int ignored){Session existing=sessions.get(p.getUniqueId());if(existing!=null){p.openInventory(existing.inv);return;}Inventory inv=Bukkit.createInventory(new MenuHolder("anvil-enchant:"+p.getUniqueId()),27,CC.color("&8Anvil"));Session s=new Session(inv);sessions.put(p.getUniqueId(),s);render(p,s);p.openInventory(inv);}

 @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getInventory().getHolder() instanceof MenuHolder(String t))||!t.startsWith("anvil-enchant:")||!(e.getWhoClicked() instanceof Player p))return;Session s=sessions.get(p.getUniqueId());if(s==null){e.setCancelled(true);return;}
  int raw=e.getRawSlot();if(e.getClick()==ClickType.DOUBLE_CLICK){e.setCancelled(true);return;}if(e.getClick()==ClickType.NUMBER_KEY&&INPUTS.contains(raw)){ItemStack hotbar=p.getInventory().getItem(e.getHotbarButton());boolean valid=hotbar==null||hotbar.getType().isAir()||(raw==11?isItemInput(hotbar):isModifier(hotbar));if(!valid){e.setCancelled(true);p.sendMessage(CC.color("&cThat hotbar item is not valid for this slot."));return;}Bukkit.getScheduler().runTask(plugin,()->render(p,s));return;}
  if(e.isShiftClick()){e.setCancelled(true);if(raw>=27){ItemStack moving=e.getCurrentItem();int target=isItemInput(moving)?11:isModifier(moving)?13:-1;if(target<0||s.inv.getItem(target)!=null){if(target<0)p.sendMessage(CC.color("&cThat item is not valid for this anvil slot."));return;}s.inv.setItem(target,moving.clone());e.setCurrentItem(null);Bukkit.getScheduler().runTask(plugin,()->render(p,s));}return;}
  if(INPUTS.contains(raw)){ItemStack cursor=e.getCursor();if(cursor!=null&&!cursor.getType().isAir()){boolean valid=raw==11?isItemInput(cursor):isModifier(cursor);if(!valid){e.setCancelled(true);p.sendMessage(CC.color(raw==11?"&cYou cannot modify that item.":"&cThat is not a registered anvil modifier."));return;}}Bukkit.getScheduler().runTask(plugin,()->render(p,s));return;}
  if(raw>=27){return;}
  e.setCancelled(true);String action=action(e.getCurrentItem());if(action==null)return;if(action.equals("close")){p.closeInventory();return;}if(action.equals("confirm"))confirm(p,s);
 }
 @EventHandler public void drag(InventoryDragEvent e){if(!(e.getInventory().getHolder() instanceof MenuHolder(String t))||!t.startsWith("anvil-enchant:"))return;if(e.getRawSlots().stream().anyMatch(slot->!INPUTS.contains(slot))){e.setCancelled(true);return;}ItemStack cursor=e.getOldCursor();for(int slot:e.getRawSlots()){if(slot==11&&!isItemInput(cursor)||slot==13&&!isModifier(cursor)){e.setCancelled(true);return;}}if(e.getWhoClicked() instanceof Player p){Session s=sessions.get(p.getUniqueId());if(s!=null)Bukkit.getScheduler().runTask(plugin,()->render(p,s));}}
 @EventHandler public void close(InventoryCloseEvent e){if(!(e.getInventory().getHolder() instanceof MenuHolder(String t))||!t.startsWith("anvil-enchant:"))return;Session s=sessions.remove(e.getPlayer().getUniqueId());if(s!=null&&e.getPlayer() instanceof Player p)returnInputs(p,s);}

 private void render(Player p,Session s){ItemStack left=s.inv.getItem(11),modifier=s.inv.getItem(13);for(int i=0;i<27;i++)if(!INPUTS.contains(i))s.inv.setItem(i,null);Preview preview=preview(p,left,modifier);s.preview=preview;
  List<String> previewLore=preview.kind.equals("reforge")?reforgePreviewLore(preview):List.of("","&7Cost: &6"+preview.coins+" Coins","&7XP Cost: &b"+preview.xp,"&7Result: &aReady","","&eClick Confirm to apply!");
  s.inv.setItem(15,preview.valid?decorate(preview.result.clone(),previewLore):button(Material.BARRIER,"&cInvalid Combination",List.of(preview.reason),null));
  s.inv.setItem(18,button(Material.PAPER,"&eSMP Anvil",List.of("&7Left: item to modify","&7Middle: book, reforge stone,","&7or registered upgrade modifier."),null));s.inv.setItem(22,button(preview.valid?Material.LIME_CONCRETE:Material.RED_CONCRETE,preview.valid?"&aConfirm / Apply":"&cCannot Apply",List.of(preview.valid?"&eClick to apply the preview.":"&7Invalid combination."),preview.valid?"confirm":null));s.inv.setItem(26,button(Material.BARRIER,"&cClose",List.of("&7Both inputs will be returned."),"close"));ItemStack pane=button(Material.BLACK_STAINED_GLASS_PANE," ",List.of(),null);for(int i=0;i<27;i++)if(s.inv.getItem(i)==null&&!INPUTS.contains(i))s.inv.setItem(i,pane);
 }
 private Preview preview(Player player,ItemStack left,ItemStack modifier){if(left==null||left.getType().isAir())return Preview.invalid("&cPlace a valid item in the first slot.");if(modifier==null||modifier.getType().isAir())return Preview.invalid("&cPlace a valid Reforge Stone in the second slot.");ReforgeManager.Definition reforge=reforges.stoneDefinition(modifier);if(reforge!=null){if(!reforges.canReforge(left,reforge))return Preview.invalid("&cThis reforge cannot be applied to that item.");String rarity=items.getCustomItemRarity(left);ItemStack result=reforges.apply(left,reforge,rarity,player.getUniqueId());return new Preview(true,result,reforges.cost(rarity),0,"reforge",reforge.id(),"");}if(!isItemInput(left)||!isModifier(modifier))return Preview.invalid("&cInvalid anvil combination.");ItemStack result=left.clone();int coins=500,xp=5;ItemMeta modifierMeta=modifier.getItemMeta();if(modifierMeta!=null){Integer configuredCoins=modifierMeta.getPersistentDataContainer().get(new NamespacedKey(plugin,"anvil_coin_cost"),PersistentDataType.INTEGER);Integer configuredXp=modifierMeta.getPersistentDataContainer().get(new NamespacedKey(plugin,"anvil_xp_cost"),PersistentDataType.INTEGER);if(configuredCoins!=null)coins=Math.max(0,configuredCoins);if(configuredXp!=null)xp=Math.max(0,configuredXp);}
  Map<String,Integer> custom=enchants.modifierEnchants(modifier);if(!custom.isEmpty()){if(blockedFlag(left,"enchant_allowed"))return Preview.invalid("&cInvalid anvil combination.");for(var entry:custom.entrySet()){int current=enchants.appliedEnchants(result).getOrDefault(entry.getKey(),0);var definition=enchants.get(entry.getKey());if(definition==null||!enchants.canApply(result,entry.getKey())||current>=definition.maxLevel())return Preview.invalid("&cInvalid anvil combination.");var applied=enchants.applyEnchant(result,entry.getKey(),entry.getValue());if(!applied.success())return Preview.invalid("&cInvalid anvil combination.");coins=Math.max(coins,cost(entry.getValue()));xp=Math.max(xp,xpCost(entry.getValue()));}return new Preview(true,result,coins,xp,"enchant",custom.keySet().iterator().next(),"");}
  if(modifier.getItemMeta() instanceof EnchantmentStorageMeta book&&!book.getStoredEnchants().isEmpty()){if(blockedFlag(left,"enchant_allowed"))return Preview.invalid("&cInvalid anvil combination.");for(var entry:book.getStoredEnchants().entrySet()){if(!entry.getKey().canEnchantItem(result))return Preview.invalid("&cInvalid anvil combination.");ItemMeta meta=result.getItemMeta();if(meta.getEnchantLevel(entry.getKey())>=entry.getValue())return Preview.invalid("&cInvalid anvil combination.");meta.addEnchant(entry.getKey(),entry.getValue(),false);result.setItemMeta(meta);coins=Math.max(coins,cost(entry.getValue()));xp=Math.max(xp,xpCost(entry.getValue()));}return new Preview(true,result,coins,xp,"vanilla_enchant","book","");}return Preview.invalid("&cInvalid anvil combination.");}
 private void confirm(Player p,Session s){Preview preview=preview(p,s.inv.getItem(11),s.inv.getItem(13));if(!preview.valid){p.sendMessage(CC.color(preview.reason));render(p,s);return;}if(economy.getCoins(p)<preview.coins){p.sendMessage(CC.color("&cYou do not have enough Coins."));return;}if(p.getLevel()<preview.xp){p.sendMessage(CC.color("&cYou do not have enough XP."));return;}if(!economy.takeCoins(p.getUniqueId(),preview.coins,"smp anvil "+preview.kind)){p.sendMessage(CC.color("&cYou do not have enough Coins."));return;}p.setLevel(p.getLevel()-preview.xp);consumeOne(s.inv,13);if(preview.kind.equals("reforge")&&items.getItemId(preview.result)!=null){items.rebuildLoreFor(p,preview.result);reforges.decorate(preview.result);plugin.getMmoStatService().refreshPlayerMMOStats(p);}s.inv.setItem(11,preview.result);if(preview.kind.equals("enchant")||preview.kind.equals("vanilla_enchant"))plugin.getSkillManager().addXp(p,"enchanting",20+preview.xp*2);p.playSound(p.getLocation(),Sound.BLOCK_ANVIL_USE,1,1.1f);ReforgeManager.Definition applied=reforges.get(preview.id);p.sendMessage(CC.color(preview.kind.equals("reforge")?"&aApplied &b"+applied.displayName()+" &ato &f"+plainName(preview.result)+"&a!":"&aApplied the enchantment to your item&a."));render(p,s);}
 private boolean isItemInput(ItemStack item){if(item==null||item.getType().isAir()||menuItem(item))return false;boolean reforgeable=reforges.all().stream().anyMatch(definition->reforges.canReforge(item,definition));return reforgeable||enchants.all().stream().anyMatch(e->enchants.canApply(item,e.id()));}
 private boolean isModifier(ItemStack item){return item!=null&&!item.getType().isAir()&&!menuItem(item)&&(reforges.stoneDefinition(item)!=null||enchants.isEnchantModifier(item)||item.getItemMeta() instanceof EnchantmentStorageMeta m&&!m.getStoredEnchants().isEmpty()||items.getFlag(item,"anvil_modifier"));}
 private boolean menuItem(ItemStack item){return item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().getKeys().stream().anyMatch(k->k.getKey().contains("menu_")||k.getKey().contains("preview"));}
 private boolean blockedFlag(ItemStack item,String name){if(item==null||!item.hasItemMeta())return false;for(NamespacedKey key:item.getItemMeta().getPersistentDataContainer().getKeys())if(key.getKey().equals(name)){Byte value=item.getItemMeta().getPersistentDataContainer().get(key,PersistentDataType.BYTE);return value!=null&&value==0;}return false;}
 private void consumeOne(Inventory inv,int slot){ItemStack item=inv.getItem(slot);if(item==null)return;if(item.getAmount()<=1)inv.setItem(slot,null);else{item=item.clone();item.setAmount(item.getAmount()-1);inv.setItem(slot,item);}}
 private void returnInputs(Player p,Session s){for(int slot:INPUTS){ItemStack item=s.inv.getItem(slot);s.inv.setItem(slot,null);if(item!=null)p.getInventory().addItem(item).values().forEach(x->p.getWorld().dropItemNaturally(p.getLocation(),x));}}
 private int cost(int level){return switch(level){case 1->500;case 2->1500;case 3->5000;case 4->15000;default->40000;};}private int xpCost(int level){return switch(level){case 1->5;case 2->10;case 3->20;case 4->30;default->40;};}
 private ItemStack decorate(ItemStack item,List<String> extra){ItemMeta meta=item.getItemMeta();List<String> lore=meta.hasLore()?new ArrayList<>(meta.getLore()):new ArrayList<>();extra.stream().map(CC::color).forEach(lore::add);meta.setLore(lore);item.setItemMeta(meta);return item;}
 private ItemStack button(Material m,String n,List<String> lore,String action){ItemStack i=new ItemStack(m);ItemMeta meta=i.getItemMeta();meta.setDisplayName(CC.color(n));meta.setLore(lore.stream().map(CC::color).toList());if(action!=null)meta.getPersistentDataContainer().set(actionKey,PersistentDataType.STRING,action);i.setItemMeta(meta);return i;}private String action(ItemStack i){return i==null||!i.hasItemMeta()?null:i.getItemMeta().getPersistentDataContainer().get(actionKey,PersistentDataType.STRING);}
 private List<String> reforgePreviewLore(Preview preview){List<String> lore=new ArrayList<>();ReforgeManager.Definition definition=reforges.get(preview.id);lore.add("");lore.add("&7Reforge: &b"+definition.displayName());lore.add("&7Cost: &6"+preview.coins+" Coins");lore.add("");lore.add("&7Stats Added:");String rarity=items.getCustomItemRarity(preview.result);for(var entry:reforges.stats(definition,rarity).values().entrySet())lore.add(entry.getKey().color()+"+"+format(entry.getValue())+(entry.getKey().percent()?"%":"")+" "+entry.getKey().display());lore.add("");lore.add("&eClick Confirm to apply!");return lore;}
 private String format(double value){return value==Math.rint(value)?String.valueOf((long)value):String.format(Locale.US,"%.1f",value);}
 private String plainName(ItemStack item){if(item==null||!item.hasItemMeta()||!item.getItemMeta().hasDisplayName())return "item";String value=ChatColor.stripColor(item.getItemMeta().getDisplayName());return value==null?"item":value;}
 public String validateMenu(){return "size=27, itemSlot=11, modifierSlot=13, previewSlot=15, confirmSlot=22, inputReturn=true, "+reforges.validation();}public String validateReforges(){return reforges.validation();}public void shutdown(){for(var e:new ArrayList<>(sessions.entrySet())){Player p=Bukkit.getPlayer(e.getKey());if(p!=null)returnInputs(p,e.getValue());}sessions.clear();}
 private static final class Session{final Inventory inv;Preview preview;Session(Inventory inv){this.inv=inv;}}private record Preview(boolean valid,ItemStack result,int coins,int xp,String kind,String id,String reason){static Preview invalid(String reason){return new Preview(false,null,0,0,"","",reason);}}
}
